// Output-centric exact Galerkin aggregation. Eight lanes own one output block,
// one lane per spatial corner. Each original fine/coarse input occurs once;
// sums stay wide, and only one owner writes each output. No shared atomics.
// Masks are generated from the existing mgCoarseStep/Kuhn offset rule.
__device__ const int g_mgGatherOffsets[15]={0,1,3,4,9,10,12,13,14,16,17,22,23,25,26};
__device__ const unsigned g_mgGatherFineMasks[120]={0x1u,0x2u,0x4u,0x8u,0x10u,0x20u,0x40u,0x7f80u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x3u,0x0u,0xcu,0x0u,0x30u,0x0u,0x2ac0u,0x5500u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x5u,0xau,0x0u,0x0u,0x50u,0x19a0u,0x0u,0x6600u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0xfu,0x0u,0x0u,0x0u,0x8f0u,0x1100u,0x2200u,0x4400u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x11u,0x22u,0x44u,0x788u,0x0u,0x0u,0x0u,0x7800u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x33u,0x0u,0x2ccu,0x500u,0x0u,0x0u,0x2800u,0x5000u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x55u,0x1aau,0x0u,0x600u,0x0u,0x1800u,0x0u,0x6000u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0xffu,0x100u,0x200u,0x400u,0x800u,0x1000u,0x2000u,0x4000u};
__device__ const unsigned g_mgGatherCoarseMasks[120]={0x1u,0x2u,0x8u,0x10u,0x200u,0x400u,0x1000u,0x6c36000u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x3u,0x0u,0x18u,0x0u,0x600u,0x0u,0x2413000u,0x4824000u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x9u,0x12u,0x0u,0x0u,0x1200u,0xc06400u,0x0u,0x6030000u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x1bu,0x0u,0x0u,0x0u,0x403600u,0x804000u,0x2010000u,0x4020000u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x201u,0x402u,0x1008u,0x36010u,0x0u,0x0u,0x0u,0x6c00000u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x603u,0x0u,0x13018u,0x24000u,0x0u,0x0u,0x2400000u,0x4800000u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x1209u,0x6412u,0x0u,0x30000u,0x0u,0xc00000u,0x0u,0x6000000u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x0u,0x361bu,0x4000u,0x10000u,0x20000u,0x400000u,0x800000u,0x2000000u,0x4000000u};
__device__ inline void mgGatherFinish(MultigridLevel& L,int C,int output,int corner,bool valid,MgReduction (&sum)[9]){
    __syncwarp(0xffffffff);
    #pragma unroll
    for(int shift=4;shift;shift/=2)
        #pragma unroll
        for(int k=0;k<9;k++)sum[k]+=__shfl_down_sync(0xffffffff,sum[k],shift,8);
    if(valid && corner==0){float values[9];for(int k=0;k<9;k++)values[k]=(float)sum[k];mgFinish(L,C,output,values);}
}
__global__ void k_MgGatherFine(const UnifiedState* state,const __half* matrix,const float* blockScale,
    const unsigned short* stencil,MultigridLevel L){
    const auto& s=*state;int target=threadIdx.x/8,corner=threadIdx.x%8;
    bool valid=target<15;int output=valid?g_mgGatherOffsets[target]:0;
    int px=corner&1,py=(corner>>1)&1,pz=corner>>2,count=min(*L.count,L.capacity);
    for(int C=blockIdx.x;C<count;C+=gridDim.x){
        MgReduction sum[9]={};
        if(valid){
            int site=L.site[C],X=site%L.sx,Y=(site/L.sx)%L.sy,Z=site/(L.sx*L.sy);
            int x=2*X+px,y=2*Y+py,z=2*Z+pz,i=x+s.nx*(y+s.ny*z);
            unsigned mask=x<s.nx && y<s.ny && z<s.n/(s.nx*s.ny) && L.parent[i]==C?stencil[i]:0;
            mask=(mask>>7&1)?mask&g_mgGatherFineMasks[15*corner+target]:0;
            while(mask){int slot=__ffs(mask)-1;mask&=mask-1;float values[9];mgStencilBlock(s,matrix,blockScale,i,slot,values);
                #pragma unroll
                for(int k=0;k<9;k++)sum[k]+=(MgReduction)values[k];}
        }
        mgGatherFinish(L,C,output,corner,valid,sum);
    }
}
__global__ void k_MgGather(MultigridLevel child,MultigridLevel L){
    int target=threadIdx.x/8,corner=threadIdx.x%8;bool valid=target<15;
    int output=valid?g_mgGatherOffsets[target]:0,px=corner&1,py=(corner>>1)&1,pz=corner>>2,count=min(*L.count,L.capacity);
    for(int C=blockIdx.x;C<count;C+=gridDim.x){
        MgReduction sum[9]={};
        if(valid){
            int site=L.site[C],X=site%L.sx,Y=(site/L.sx)%L.sy,Z=site/(L.sx*L.sy),x=2*X+px,y=2*Y+py,z=2*Z+pz;
            if(x<child.sx && y<child.sy && z<child.sz)for(int slot=0;slot<MG_SLOTS;slot++){
                int c=child.index[MG_SLOTS*(x+child.sx*(y+child.sy*z))+slot];
                if(c<0 || L.parent[c]!=C)continue;
                unsigned mask=g_mgGatherCoarseMasks[15*corner+target];
                while(mask){int o=__ffs(mask)-1;mask&=mask-1;if(child.neighbor[27*c+o]<0)continue;
                    const float* values=child.A+(27*c+o)*9;
                    #pragma unroll
                    for(int k=0;k<9;k++)sum[k]+=(MgReduction)values[k];}
            }
        }
        mgGatherFinish(L,C,output,corner,valid,sum);
    }
}
